    private void callScannerTool() {
        List<String> missingProperties = checkProperties(arPropertyManager.getProperties());

        if (!missingProperties.isEmpty()) {

            int totalMissing = missingProperties.size();
            int partSize = (int) Math.ceil((double) totalMissing / 3); // Divide into 3 parts

            String part1 = String.join(", ", missingProperties.subList(0, Math.min(partSize, totalMissing)));
            String part2 = totalMissing > partSize
                    ? String.join(", ", missingProperties.subList(partSize, Math.min(2 * partSize, totalMissing)))
                    : "";
            String part3 = totalMissing > 2 * partSize
                    ? String.join(", ", missingProperties.subList(2 * partSize, totalMissing))
                    : "";

            performMessage.errorMessage(
                    "I cannot Execute Web Scanner", "Missing required properties: ", part1, part2, part3, 0);
            return;
        }

        if (!isScannerButtonClicked) { // Check if the button action was not already triggered
            isScannerButtonClicked = true; // Set the flag to prevent further clicks

            ARLogger.getInstance(ARViewBotJobPane.class).fine("Calling openScannerButton");

            String threadName = "botJob-" + this.botJobLoad.getId();
            arScene.startNewThread(threadName, () -> {
                executeScannerTask();
                isScannerButtonClicked = false; // Reset the flag after task completes
            });
        }
    }

    // Method where you start the thread (e.g., in a button's event handler)
    private void handleStartScanner() {
        String threadName = "botJob-" + this.botJobLoad.getId(); // Use the ID for the thread name
        arScene.startNewThread(threadName, () -> {
            executeScannerTask();
            Platform.runLater(() -> {
                // Update UI here, if needed
                System.out.println("Scanner task completed for " + threadName);
            });
        });
    }

    private void executeScannerTask() {

        HomeBankingLoadDTO homeBankingLoadDTO = performDataBase.loadHomeBanking(this.botJobLoad.getHomeBankingId());

        if (this.botJobLoad.getBlockLoadDTOList() != null
                && this.botJobLoad.getBlockLoadDTOList().size() > 0) {
            this.blockLoad = this.botJobLoad.getBlockLoadDTOList().get(0);
        } else {

            this.blockLoadList = performDataBase.loadBlocksByBotJobId(this.botJobLoad.getId());
            if (this.blockLoadList.size() > 0) {
                this.blockLoad = blockLoadList.get(0);
            }
        }

        try {
            Platform.runLater(() -> {
                try {

                    activeSessions = simpleWebSocketServer.getAllSessions();
                    // Call the ARScannedElementScene here
                    ARScannedElementScene scene =
                            arScannedElementScene.initialize(homeBankingLoadDTO, this.botJobLoad, this.blockLoad);

                    scene.show(); // Make sure the scene is shown
                } catch (Exception ex) {
                    handleExceptionScan(ex);
                }
            });
        } catch (Exception ex) {
            handleExceptionScan(ex);
        }
    }

    private void handleExceptionScan(Exception error) {
        // Log the exception
        ARLogger.getInstance(ARViewBotJobPane.class)
                .severe("ERROR Calling openScannerButton -> Cause: " + error.getMessage());

        // Display the error message to the user
        if (error.getMessage().contains("no such window: target window already closed")
                || error.getMessage().contains("web view not found")) {
            performMessage.errorMessage(
                    "Error Calling SCAN",
                    "Web Browser was closed before the Scanner Tool",
                    "Close and Re-Open the Scanner Tool",
                    null,
                    null,
                    0);
        } else {

            //            "invalid session id"

            if (!error.getMessage().contains("Current browser version")) {
                String[] lines = error.getMessage().split("\n");

                String msg1 = null;
                String msg2 = null;
                String msg3 = null;
                String msg4 = null;

                for (String line : lines) {
                    // Exclude unnecessary lines
                    if (line.contains("Host info")
                            || line.contains("Build info")
                            || line.contains("System info")
                            || line.contains("Command")) {
                        continue;
                    }

                    String message = line.contains("Message: ")
                            ? line.substring(line.indexOf("Message: ") + "Message: ".length())
                                    .trim()
                            : line.trim();

                    if (!message.isEmpty()) {
                        if (msg1 == null) {
                            msg1 = message;
                        } else if (msg2 == null) {
                            msg2 = message;
                        } else if (msg3 == null) {
                            msg3 = message;
                        } else if (msg4 == null) {
                            msg4 = message;
                        }
                    }
                }

                ARLogger.getInstance(ARViewBotJobPane.class).severe("Error Open URL: \n" + msg1 + "\n" + msg2);

                //                performMessage.errorMessage("Error Open URL", msg1, msg2, msg3, msg4, 0);
                String webDriverPath = arPropertyManager.getProperty(ARPropertyEnum.PATH_WEBDRIVER);
                if (error.getMessage().contains("session deleted as the browser has closed the connection")
                        || error.getMessage().contains("Expected condition failed: waiting for com")) {
                    performMessage.errorMessage(
                            "Interruption Calling SCAN",
                            "<span style='font-style: italic;'>Session deleted as the browser has closed the connection!</span>",
                            "<span style='color: #E65100; font-weight: bold;'>WebDriver path:</span> <span style='font-weight: bold;'>"
                                    + webDriverPath + "</span>",
                            "<span style='font-style: italic;'>Please close and Re-Open the Scanner Tool.</span>",
                            "<span style='font-style: italic;'>Details: "
                                    + "Web Browser was closed before the Scanner Tool" + "</span>",
                            0);
                } else {
                    performMessage.errorMessage(
                            "Access WebDriver",
                            "<span style='font-style: italic;'>The WebDriver data directory is probably already in use.</span>",
                            "<span style='color: #E65100; font-weight: bold;'>WebDriver path:</span> <span style='font-weight: bold;'>"
                                    + webDriverPath + "</span>",
                            "<span style='font-style: italic;'>Details: "
                                    + "Please close all possible Browser Instances" + "</span>",
                            "<span style='font-style: italic;'>Check/close all instances of the installer first.</span>",
                            0);
                }
            }
        }

        //        Platform.runLater(() -> {
        //            JOptionPane.showMessageDialog(
        //                    null,
        //                    "An error has occurred Calling SCAN: \nCause: " + ex.getMessage(),
        //                    "Error calling in SCAN",
        //                    JOptionPane.ERROR_MESSAGE);
        //        });
    }

